29	    Aws::S3::Model::HeadObjectOutcome headObject(
30	        const S3::Client & client,
31	        const String & bucket,
32	        const String & key,
33	        const String & version_id)
34	    {
35	        ProfileEvents::increment(ProfileEvents::S3HeadObject);
36	        if (client.isClientForDisk())
37	            ProfileEvents::increment(ProfileEvents::DiskS3HeadObject);
38	
39	        S3::HeadObjectRequest req;
40	        req.SetBucket(bucket);
41	        req.SetKey(key);
42	
43	        if (!version_id.empty())
44	            req.SetVersionId(version_id);
45	
46	        return client.HeadObject(req);
47	    }
