97	bool isNotFoundError(Aws::S3::S3Errors error)
98	{
99	    return error == Aws::S3::S3Errors::RESOURCE_NOT_FOUND || error == Aws::S3::S3Errors::NO_SUCH_KEY
100	        || error == Aws::S3::S3Errors::NO_SUCH_BUCKET;
101	}
