103	bool isAuthenticationError(Aws::S3::S3Errors error)
104	{
105	    return error == Aws::S3::S3Errors::ACCESS_DENIED
106	        || error == Aws::S3::S3Errors::INVALID_ACCESS_KEY_ID
107	        || error == Aws::S3::S3Errors::INVALID_SIGNATURE;
108	}
109	
110	String getAuthenticationErrorHint(Aws::S3::S3Errors error)
111	{
112	    if (isAuthenticationError(error))
113	        return " Please check your AWS credentials and permissions.";
114	    return "";
115	}
