142	ObjectInfo getObjectInfoIfExists(
143	    const S3::Client & client,
144	    const String & bucket,
145	    const String & key,
146	    const String & version_id,
147	    bool with_metadata,
148	    bool with_tags)
149	{
150	    Expect404ResponseScope scope; // 404 is not an error
151	
152	    auto [object_info, error] = tryGetObjectInfo(client, bucket, key, version_id, with_metadata, with_tags);
153	    if (object_info)
154	        return *object_info;
155	
