199	bool objectExists(
200	    const S3::Client & client,
201	    const String & bucket,
202	    const String & key,
203	    const String & version_id)
204	{
205	    Expect404ResponseScope scope; // 404 is not an error
206	
207	    auto [object_info, error] = tryGetObjectInfo(client, bucket, key, version_id, {}, {});
208	
209	    if (object_info)
210	        return true;
211	
212	    if (isNotFoundError(error.GetErrorType()))
213	        return false;
214	
215	    throw S3Exception(error.GetErrorType(),
216	        "Failed to check existence of key {} in bucket {}: {}. HTTP response code: {}, error type: {}.{}",
217	        key, bucket, error.GetMessage(), static_cast<size_t>(error.GetResponseCode()),
218	        error.GetErrorType(), getAuthenticationErrorHint(error.GetErrorType()));
219	}
