222	    const S3::Client & client,
223	    const String & bucket,
224	    const String & key,
225	    const String & version_id,
226	    std::string_view description)
227	{
228	    auto [object_info, error] = tryGetObjectInfo(client, bucket, key, version_id, {}, {});
229	    if (object_info)
230	        return;
231	    throw S3Exception(error.GetErrorType(), "{}Object {} in bucket {} suddenly disappeared: {}",
232	                        (description.empty() ? "" : (String(description) + ": ")), key, bucket, error.GetMessage());
233	}
